import{_ as t,h as i,i as a,c as n,v as l,p as s,x as r,m as B,e as M,S as d}from"./chunks/framework.Dvtg8yj2.js";const C=JSON.parse('{"title":"HBM 与算力墙","description":"","frontmatter":{"title":"HBM 与算力墙","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/hbm-roofline.md","filePath":"llm/hbm-roofline.md","lastUpdated":1788454257000}'),h={name:"llm/hbm-roofline.md"};function A(c,e,P,p,m,E){const o=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=l('<h1 id="hbm-与算力墙" tabindex="-1">HBM 与算力墙 <a class="header-anchor" href="#hbm-与算力墙" aria-label="Permalink to &quot;HBM 与算力墙&quot;">​</a></h1><div class="epigraph"><p>当运算强度低于峰值算力与峰值带宽之比，加 FLOPS 几乎不降墙钟；时间由把字节从 HBM 搬到片上决定。</p><footer>—— Williams, Waterman, Patterson, Roofline: An Insightful Visual Performance Model for Multicore Architectures, CACM 2009</footer></div><p>GPU 产品表同时印两行大数：Tensor Core 峰值与 HBM 带宽。训练 prefill 与大 GEMM 容易靠近第一行；自回归 decode、小 batch、以及任何「每步扫一遍权重」的工作点靠近第二行。Williams 等人的屋顶线把这两行收成一条折线：横轴是算术强度（FLOP / Byte），纵轴是可达 FLOPS。拐点左侧叫带宽墙，右侧叫算力墙。本篇把这条折线接到 Ampere / Hopper / Blackwell 的<strong>已公布</strong> HBM 规格，以及 LLM 里常见的强度范围。不编造未出现在数据手册里的实测带宽，也不把某一代的营销 TFLOPS 当成屋顶线上的可达点。</p><p>Decode 侧的专用讨论见 <a href="/llm/decode-memory-wall">Decode 的显存墙</a>；这里把模型写完整，并对照三代 GPU 的公开带宽。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>峰值算力 \\(P\\) 与峰值带宽 \\(B\\) 给出拐点强度</p> \\[I_{\\mathrm{ridge}} = \\frac{P}{B}. \\]<p>工作负载的强度 \\(I\\) 若小于 \\(I_{\\mathrm{ridge}}\\)，可达性能 \\(\\min(P, I\\cdot B)\\) 落在斜边上，加 \\(P\\) 无用，加 \\(B\\) 或减字节才有用。若 \\(I\\) 远大于拐点，才值得堆 Tensor Core。问题是：LLM 的不同阶段 \\(I\\) 差几个数量级，而产品迭代里 \\(P\\) 往往比 \\(B\\) 涨得更快，拐点右移，越来越多曾经「算得动」的核掉进带宽墙。</p><p>公开规格（NVIDIA 数据手册 / 产品页）：A100 80GB SXM 的 HBM2e 带宽约 2.039 TB/s；H100 SXM 的 HBM3 为 3.35 TB/s；H100 产品页给出稀疏 FP16 Tensor Core 1,979 TFLOPS、稀疏 FP8 3,958 TFLOPS。Blackwell 产品材料给出 B200 类 GPU 约 8 TB/s 的 HBM3e 与第五代 Tensor Core（含 FP4）。同一代里 \\(P\\) 随精度变，\\(B\\) 不变，所以 FP8 / FP4 的拐点比 FP16 更靠右——精度越低，越容易变成「算力过剩、HBM 不够」。</p><h3 id="算术强度从哪来" tabindex="-1">算术强度从哪来 <a class="header-anchor" href="#算术强度从哪来" aria-label="Permalink to &quot;算术强度从哪来&quot;">​</a></h3><p>对形状 \\((M,N,K)\\) 的 GEMM，FLOP 约 \\(2MNK\\)，进出字节约 \\((MK+KN+MN)\\) 乘以元素宽度（忽略缓存命中）。\\(M,N,K\\) 都大时 \\(I\\) 高，prefill 的长序列、宽 hidden、大 batch 落在这里。\\(M\\) 变成 1 或小 batch，强度按 \\(K\\) 与 \\(N\\) 摊不薄，decode 的 MLP 就掉到斜边。注意力还多一项：从 HBM 读 KV，FLOP 随序列长度 \\(n\\) 长，字节也随 \\(n\\) 长，强度不一定救得回来，尤其是 GQA 仍要扫 \\(n\\) 上的键值。</p><p>权重若每步都从 HBM 完整扫一遍，相当于在强度公式里加了一大块只读流量。连续批处理让同一份权重乘在许多序列上，等于增大 \\(M\\)，强度上升。这是服务系统用 batch 换利用率的屋顶线解释，而不只是「提高占用」。</p><p><span class="marginnote">屋顶线用的 \\(B\\) 是 DRAM / HBM 峰值。片上 SRAM、L2 命中会把有效 \\(B\\) 变大、有效 \\(I\\) 变高。FlashAttention 一类把 \\(I\\) 从「每次都回 HBM」改成「块在 SRAM 里重用」，是在移动工作点，不是改 \\(P\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先估强度，再对墙。不要先换卡。</p><ol><li>写出这一步的 FLOP 与必须进出 HBM 的字节（权重、激活、KV、梯度）。</li><li>用对应精度的 \\(P\\) 与该卡公开 \\(B\\) 算 \\(I_{\\mathrm{ridge}}\\)。注意产品表 Tensor Core 常给 <strong>sparse</strong> 峰值，dense 往往是一半；拐点要用你真正跑的那一档。</li><li>比较 \\(I\\) 与 \\(I_{\\mathrm{ridge}}\\)。在斜边上：量化、GQA/MLA、更大 batch、更好的融合、换更高 \\(B\\) 的 SKU。在平台上：切更大的 GEMM、用 Tensor Core 数据类型、减少非 MMA 的标量开销。</li></ol>',16)),(a(),s(d,null,{default:r(()=>[M(o,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20LR%0A%20%20I%5B%22%E7%AE%97%E6%9C%AF%E5%BC%BA%E5%BA%A6%20I%22%5D%20--%3E%20CMP%7B%22I%20%E7%9B%B8%E5%AF%B9%20P%2FB%22%7D%0A%20%20CMP%20--%3E%7C%22I%20%E5%B0%8F%22%7C%20MEM%5B%22%E5%B8%A6%E5%AE%BD%E5%A2%99%EF%BC%9A%E5%8A%A0%20B%20%E6%88%96%E5%87%8F%E5%AD%97%E8%8A%82%22%5D%0A%20%20CMP%20--%3E%7C%22I%20%E5%A4%A7%22%7C%20CMPW%5B%22%E7%AE%97%E5%8A%9B%E5%A2%99%EF%BC%9A%E5%8A%A0%20Tensor%20Core%22%5D%0A%20%20MEM%20--%3E%20Q%5B%22%E9%87%8F%E5%8C%96%20%2F%20%E8%9E%8D%E5%90%88%20%2F%20batch%22%5D%0A%20%20CMPW%20--%3E%20TC%5B%22MMA%20%E7%B2%BE%E5%BA%A6%E4%B8%8E%E5%BD%A2%E7%8A%B6%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[B(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<p>对已公布带宽做量级对照（均为厂商规格，不是本博客测量）：A100 80GB 约 2.0 TB/s，H100 SXM 3.35 TB/s，H200 产品页给出更高容量的 HBM3e 与约 4.8 TB/s 量级，Blackwell 公开材料约 8 TB/s。从 A100 到 H100，带宽约 1.6 倍，稀疏 FP8 相对 A100 的 FP16 峰值却是另一档倍数——拐点右移。换代若只看 TFLOPS 表，会高估 decode 收益。</p><h3 id="llm-三个工作点" tabindex="-1">LLM 三个工作点 <a class="header-anchor" href="#llm-三个工作点" aria-label="Permalink to &quot;LLM 三个工作点&quot;">​</a></h3><p>Prefill：序列长、GEMM 胖，\\(I\\) 高，容易算力墙或至少靠近拐点。FlashAttention 减少的是注意力的 HBM 往返，使这块更接近计算屋顶，见 <a href="/llm/flashattention">FlashAttention</a>。Decode：每步 \\(M\\) 小，权重流量大，\\(I\\) 低，几乎总在带宽墙，见 <a href="/llm/decode-memory-wall">显存墙</a>。MoE 专家若按 token 稀疏点名，还要加「只加载被点到的专家」的随机流量，强度更碎，域内 All-to-All 会再插入 NVLink 墙，那是互连屋顶线，不是 HBM 屋顶线。</p><p>同一张卡上，TF32 / FP16 / FP8 / FP4 的 \\(P\\) 不同，\\(B\\) 相同。把权重从 FP16 换成 FP8，字节减半，\\(I\\) 的分子若按 FLOP 不变（仍是一次 FMA），则 \\(I\\) 上升，有可能从斜边爬向拐点。这是低精度既减流量又对上 Tensor Core 的双重作用。反过来，若 kernel 没有走 MMA、只是用低精度存数据，你减了字节却没用上 \\(P\\)，仍可能停在斜边。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>屋顶线成立，是因为片外存储器的引脚与功耗限制了 \\(B\\)，而计算阵列的峰值 \\(P\\) 可以靠更宽的 MMA 与更低精度涨得更快。HBM 把 DRAM 竖在逻辑芯片边上，提高 \\(B\\)，但每一代 HBM 的涨幅通常小于 Tensor Core 表头的涨幅。于是「算力墙」的平台越来越短，「带宽墙」的斜边越来越长。Williams 原文画的是 CPU 与 DRAM；GPU 只是把 DRAM 换成 HBM、把核心换成 SM + Tensor Core，几何形状不变。</p><p>有效带宽 \\(\\eta_b B\\) 永远低于标称 \\(B\\)。对齐、访问粒度、多 kernel 争用、ECC、以及没有 coalesced 的 KV 读取，都会打 \\(\\eta_b\\)。有效算力 \\(\\eta_c P\\) 同样：形状不满足 MMA tile、没有走稀疏路径、启动开销，都会打 \\(\\eta_c\\)。屋顶线给出的是上界折线；工程落在折线之下。调优先问掉在哪一段，再问 \\(\\eta\\)。</p><p><span class="marginnote">NVLink 1.8 TB/s 与 HBM 8 TB/s 量级不是同一条屋顶线。远程集合通信应另画一条「互连屋顶」。把 130 TB/s 域聚合拿来当单卡 \\(B\\)，会把拐点算错两个数量级。</span></p><h3 id="容量墙不是带宽墙" tabindex="-1">容量墙不是带宽墙 <a class="header-anchor" href="#容量墙不是带宽墙" aria-label="Permalink to &quot;容量墙不是带宽墙&quot;">​</a></h3><p>HBM 还有容量一维：放不下则 OOM 或换出。容量墙用量化、并行切分、KV 压缩来解；带宽墙用减流量与加 \\(B\\) 来解。一张 80GB 的卡可以「放得下却跑不满吞吐」，另一张更大容量但 \\(B\\) 相近的卡只解 OOM。H200 相对 H100 的公开故事是容量与带宽一起加，对长上下文更对症。Blackwell 的更大 HBM3e 同样先解容量，再解 \\(B\\)。不要用「显存更大」当「decode 一定更快」的充分条件——还要看 \\(B\\) 与 batch。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用 sparse 峰值去除 dense 工作负载的 FLOP。不要在屋顶线图上标自己估的「实际 70% 带宽」却写成 NVIDIA 规格。不要把 L2 命中率很高的小核当成 HBM 墙的反例——它已经不在这条折线上。不要为了爬上平台而盲目加大 batch：服务延迟 SLA 会先炸。</p><p>CPU 屋顶线、GPU 屋顶线、集群互连屋顶线要分图。超节点的集合通信受 NVLink 约束，见 <a href="/llm/supernode-memory-collectives">超节点内存与集合通信</a>。片上 SRAM 优化（FlashAttention、融合 MLP）改变的是有效字节，应画进 \\(I\\)，而不是修改 \\(B\\) 的标称。</p><p><span class="marginnote">出处：Williams et al., CACM 2009；带宽与峰值来自 NVIDIA A100 / H100 / Blackwell 产品页与数据手册。未列出的 SKU 带宽以对应手册为准，本文不补。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>屋顶线：可达 FLOPS \\(= \\min(P, I\\cdot B)\\)；拐点 \\(P/B\\) 随精度与代际右移。</li><li>公开对照：A100 80GB 约 2.0 TB/s，H100 SXM 3.35 TB/s，Blackwell 公开材料约 8 TB/s HBM3e；\\(P\\) 涨得更快，decode 更容易带宽受限。</li><li>Prefill 偏算力墙，decode 偏带宽墙；低精度同时减字节与对齐 Tensor Core。</li><li>有效带宽与有效算力都有 \\(\\eta\\)；屋顶线是上界。</li><li>容量墙与带宽墙分开解；NVLink 是第三条屋顶线。</li><li>出处：Williams et al., CACM 2009；NVIDIA 公开规格。</li></ul>',16))])}const F=t(h,[["render",A]]);export{C as __pageData,F as default};
